import { createHash } from 'node:crypto';

// Snapshot of the Korean strings already published in the 2026-10-30 draft.
// The 124 question statements were independently found as exact literals in
// the pinned 331,501-byte public client JS (SHA-256 below). Option captions
// additionally include labels generated by the client's scale UI. These
// hashes prevent silent source-text drift; they do NOT prove copyright rights,
// human translation review, hidden paths, or official scoring equivalence.
export const KOREAN_SOURCE_SNAPSHOT = Object.freeze({
  sourceAssetSha256: '59a67f9d1e0049156bedfe4d61a4cf8511dc8903ba80cf297b6bffad3c2b379e',
  questionTextSha256: 'e3f1a365200baf882c9ffa1f874d8004356ccfc2c55906689e973ca1c0bbd0f9',
  optionLabelsSha256: '3d418f913d975e7457d19679bc8317d47fc52d1a40fd3b122b1f472d9452e63a',
  sourceMetadataSha256: '3fed3169732ee94e26bc8ee5a28a5133bdd9996a37cd8780e3675e6d5fa326e1',
});

function hashJson(value) {
  return createHash('sha256').update(JSON.stringify(value)).digest('hex');
}

/**
 * Bind the source-client hash to question IDs, order, raw option values
 * and reverse/agree-side metadata. The Korean-text snapshot alone does
 * not detect coordinated edits to the draft and source index.
 * No copyrighted question prose or personal answers are hashed here.
 */
export function fingerprintSourceMetadata(index) {
  const value = {
    sourceAssetSha256: index?.sourceAssetSha256,
    sourceAssetBytes: index?.sourceAssetBytes,
    groups: index?.groups?.map(g => [
      g.season, g.sourceGroup, g.count, g.optionCount,
      g.reverseFlagCount, g.sourceArraySha256,
    ]),
    questions: index?.questions?.map(q => [
      q.season, q.sourceQuestionId, q.sourceGroup,
      q.sourceArrayPosition, q.displayPositionDerivedFromClient,
      q.optionCount, q.optionValues,
      q.reverseFlagInPublicClient, q.agreeSideInPublicClient ?? null,
    ]),
  };
  return hashJson(value);
}

export function verifySourceMetadataSnapshot(index) {
  if (index?.sourceAssetSha256 !== KOREAN_SOURCE_SNAPSHOT.sourceAssetSha256 ||
      fingerprintSourceMetadata(index) !== KOREAN_SOURCE_SNAPSHOT.sourceMetadataSha256) {
    throw new Error('源题元数据指纹不匹配：须先独立核对当前公开客户端的题号、选项值、顺序与方向');
  }
  return true;
}

/**
 * Build-time-only gate. A translator may edit Chinese draft copy independently,
 * but changing Korean source text or Korean option captions requires a
 * deliberate re-evaluation of the pinned source snapshot.
 */
export function verifyKoreanSourceSnapshot(pack) {
  const questions = [...(pack?.seasons?.[1] || []), ...(pack?.seasons?.[2] || [])];
  if (pack?.sourceSha256 !== KOREAN_SOURCE_SNAPSHOT.sourceAssetSha256 ||
      questions.length !== 124 ||
      questions.reduce((total, q) => total + q.options.length, 0) !== 550) {
    throw new Error('韩文来源快照：源资源版本或题目数量变化，禁止静默发布');
  }
  const questionText = hashJson(questions.map(q => [q.season, q.id, q.sourceKo]));
  const optionLabels = hashJson(questions.flatMap(q =>
    q.options.map(o => [q.season, q.id, o.value, o.ko])));
  if (questionText !== KOREAN_SOURCE_SNAPSHOT.questionTextSha256 ||
      optionLabels !== KOREAN_SOURCE_SNAPSHOT.optionLabelsSha256) {
    throw new Error('韩文来源快照：题干或选项韩文与已核验草稿不一致，需重新核对原始客户端');
  }
  return true;
}
